#!/usr/bin/env bats
load bats-extra

# parsing and numbers
@test numbers_only {
    #[[ $BATS_RUN_SKIPPED == "true" ]] || skip
    run gawk -f forth.awk <<END
1 2 3 4 5
END
    assert_success
    assert_output "1 2 3 4 5"
}

@test "pushes negative numbers onto the stack" {
    [[ $BATS_RUN_SKIPPED == "true" ]] || skip
    run gawk -f forth.awk <<END
-1 -2 -3 -4 -5
END
    assert_success
    assert_output "-1 -2 -3 -4 -5"
}

